using Xunit;

namespace AIERP.Api.IntegrationTests;

/// <summary>
/// Belge kuralları PR 2: a Belge page built by Studio's own model (frontend/development-studio …/panel/belgeModel.ts, through the
/// designer's wire step) passes the real server validator. Fixtures/Belge/definition.json is generated by the Studio vitest
/// <c>belgeServerFixture.test.ts</c> (<c>UPDATE_BELGE_FIXTURE=1 npx vitest run belgeServerFixture</c>).
/// </summary>
public sealed class TenantCustomPageBelgeStudioFixtureTests
{
    [Fact]
    public void Studio_built_belge_page_validates()
    {
        var json = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "BelgeFixtures", "definition.json"));

        Assert.True(TenantCustomPageSchema.Validate(json, out var error), error);
        Assert.Equal("belge", PageTemplateSummary.Read(json).Template);
    }
}
